{
  "name": "ble_ll_send_data_packet",
  "confidence": "medium",
  "docstring": "Transmit a Bluetooth LE link-layer data packet for a selected context, building and scheduling packets while updating command status and sequence state.",
  "subsystem": "ble",
  "var_renames": {
    "v1": "ll_index",
    "v2": "cmd_buf",
    "v3": "ll_table_base",
    "v4": "ll_ctx",
    "v5": "ctx_flags_old",
    "v6": "ctx_flags_new",
    "v7": "ll_global_config",
    "v8": "cmd_flags",
    "v9": "cmd_status_word",
    "v10": "data_request_active",
    "v11": "ll_table_entry",
    "v12": "entry_flags",
    "v13": "entry_flags_new",
    "v14": "built_data_packet",
    "v15": "next_seq"
  },
  "struct_hints": [
    {
      "offset": 29,
      "meaning": "cmd_buf: uint8 slot/context index, apparently limited to 0..31"
    },
    {
      "offset": 30,
      "meaning": "cmd_buf: uint16 status/flags; bit 0x2000 is set when control packet handling reports success"
    },
    {
      "offset": 36,
      "meaning": "cmd_buf: uint32 request flags; bit 0x200000 appears to mark an active data/advertising request"
    },
    {
      "offset": 54,
      "meaning": "cmd_buf: uint8 status/result byte; stores seq << 2 and status bits derived from ll_ctx"
    },
    {
      "offset": 166,
      "meaning": "ll_ctx: uint8 flags; bit 0x02 marks a pending/ready condition, bit 0x04 is tested together with cmd flag 0x200000"
    },
    {
      "offset": 167,
      "meaning": "ll_ctx: uint8 packet sequence counter incremented modulo 4"
    },
    {
      "offset": 168,
      "meaning": "ll_ctx: uint8 status byte copied into cmd_buf + 54 when no new data packet is built"
    },
    {
      "offset": 340,
      "meaning": "ll_table_entry: pointer to per-context ll_ctx structure"
    },
    {
      "offset": 350,
      "meaning": "ll_table_entry: uint8 flags; bits 0x11 and 0x20 mark data/control scheduling state"
    }
  ]
}
